/* ==========================================================================
   Consultant tools (My clients)
   - Client comparison: every client side by side on control score, legal
     compliance, training, appointments, high risks, overdue actions, open
     incidents, last and next consultant visit — sorted so the client that
     needs attention most is first.
   - Visit reports: plan a visit, record what was checked and the findings
     (each finding becomes a corrective action in that client), the summary
     and the next visit; consultant and client representative sign; PDF
     report e-mailed to the client's management.
   - Template library: copy a client's set-up (legal requirements, courses and
     training requirements, PPE types and requirements, risk assessments,
     audit checklists) to another client, so a new client starts complete.
   ========================================================================== */
'use strict';

const isConsultant = () => can('clients.manage') || myOrgs().length > 1;
const VISIT_AREAS = ['Legal requirements', 'Documents', 'Appointments', 'Training', 'Risk assessments', 'Assets and inspections', 'PPE', 'Hazardous substances', 'Emergency preparedness', 'Contractors', 'Incidents', 'Corrective actions', 'Site walk-through'];
const visitsOf = org => (S.visits || []).filter(v => v.org === org).sort((a, b) => b.date.localeCompare(a.date));
const lastVisit = org => visitsOf(org).find(v => v.status === 'Completed') || null;
const nextVisit = org => (S.visits || []).filter(v => v.org === org && v.status === 'Planned').sort((a, b) => a.date.localeCompare(b.date))[0] || null;
function clientStats(o) {
  return withOrg(o.id, () => { const c = compliance('ALL'), L = typeof legalCounts === 'function' ? legalCounts((S.legalReqs || []).filter(r => r.org === o.id)) : {}, T = typeof trainingSummary === 'function' ? trainingSummary(S.people.filter(p => p.org === o.id && p.status !== 'Deactivated' && p.type === 'Employee')) : {};
    const A = (S.appointments || []).filter(a => a.org === o.id), apt = A.filter(a => aptOpen(a) || a.status === 'Declined').length;
    const hi = (S.riskAssessments || []).filter(a => a.org === o.id && a.status !== 'Superseded').flatMap(a => a.rows || []).filter(r => { const b = rBand(rowRisk(r)); return b && RM().bands.indexOf(b) >= RM().bands.length - 2; }).length;
    const lv = lastVisit(o.id), nv = nextVisit(o.id);
    const score = (c.overdueActions * 3) + (L.non || 0) * 3 + (L.notAssessed || 0) + apt + hi * 2 + (T.missing || 0) + (T.expired || 0) + (nv && daysTo(nv.date) < 0 ? 5 : 0) + (!lv || daysTo(lv.date) < -90 ? 3 : 0);
    return { o, c, L, T, apt, hi, lv, nv, attention: score }; });
}

ROUTES.clients = (p = [], q = {}) => {
  if (!isConsultant()) return ROUTES.notfound();
  if (p[0] && /^VIS-/.test(p[0])) return visitDetail(p[0]);
  const tab = ['overview', 'visits', 'library'].includes(p[0]) ? p[0] : 'overview';
  const tabs = [['overview', 'Client comparison', myOrgs().length], ['visits', 'Visit reports', (S.visits || []).filter(v => myOrgs().some(o => o.id === v.org)).length], ['library', 'Template library']];
  let body = '', fab = '';
  if (tab === 'overview') { body = compareHtml(); fab = can('clients.manage') ? fabStack([{ act: 'visitNew', label: 'Plan a visit' }, { act: 'clientNew', label: 'New client', icon: 'building', cls: 'ghost' }]) : ''; }
  if (tab === 'visits') { body = visitsHtml(q); fab = fabBtn('visitNew', 'Plan a visit'); }
  if (tab === 'library') body = libraryPageHtml();
  const html = `${pageHead('My clients', 'Every client you look after, side by side, with your visits and a library to set up new clients quickly. Each client\'s records stay separate.')}${fab}${tabsHtml('#/clients', tabs, tab)}${body}`;
  return { title: 'My clients', nav: 'clients', crumbs: [['My clients', '#/clients']], html };
};
function compareHtml() {
  const R = myOrgs().map(clientStats).sort((a, b) => b.attention - a.attention), pct = (v, tone) => v == null ? '<span class="muted">—</span>' : `<span class="hm-cell st-bg-${band(v).cls}">${v}%</span>`;
  const od = R.filter(r => r.nv && daysTo(r.nv.date) < 0).length, nov = R.filter(r => !r.lv || daysTo(r.lv.date) < -90).length;
  return `<div class="kpis">${kpi('Clients', R.length, `${R.reduce((n, r) => n + orgSitesOf(r.o.id).length, 0)} branches in total`, 'blue', '#/clients', 'building')}
      ${kpi('Overdue corrective actions', R.reduce((n, r) => n + r.c.overdueActions, 0), 'Across all clients', R.some(r => r.c.overdueActions) ? 'red' : 'green', '#/clients', 'target')}
      ${kpi('Non-compliant legal requirements', R.reduce((n, r) => n + (r.L.non || 0), 0), `${R.reduce((n, r) => n + (r.L.notAssessed || 0), 0)} not assessed`, R.some(r => r.L.non) ? 'red' : 'green', '#/clients', 'scale')}
      ${kpi('Visits overdue', od, `${nov} client(s) not visited in 90 days`, od || nov ? 'amber' : 'green', '#/clients/visits', 'calendar')}</div>
    <div class="card"><div class="card-head"><h2>Clients by attention needed</h2><span class="ch-sub">The client that needs you most is first</span></div><div class="card-body flush"><div class="table-wrap"><table class="tbl compact stackable cmp"><thead><tr><th>Client</th><th>Score</th><th>Legal</th><th>Training</th><th title="Appointments waiting or declined">Appts open</th><th>High risks</th><th title="Overdue corrective actions">Overdue</th><th title="Open incidents">Incidents</th><th>Last visit</th><th>Next visit</th><th></th></tr></thead><tbody>
    ${R.map(r => `<tr class="${r.o.id === S.ui.org ? 'hm-sel' : ''}"><td data-label="Client"><div class="client-cell">${orgMark(r.o, 'cl')}<div><b>${esc(r.o.short || r.o.name)}</b><div class="t-sub">${orgSitesOf(r.o.id).length} branch(es)</div></div></div></td>
      <td data-label="Control score">${pct(r.c.overall)}</td><td data-label="Legal compliance">${pct(r.L.pct)}${r.L.non ? `<div class="t-sub due red">${r.L.non} non-compliant</div>` : ''}</td><td data-label="Training">${pct(r.T.pct)}</td>
      <td data-label="Appointments">${r.apt || '—'}</td><td data-label="High risks">${r.hi ? `<span class="due red">${r.hi}</span>` : '—'}</td><td data-label="Overdue actions">${r.c.overdueActions ? `<span class="due red">${r.c.overdueActions}</span>` : '—'}</td><td data-label="Open incidents">${r.c.openIncidents || '—'}</td>
      <td data-label="Last visit">${r.lv ? `<a href="#/clients/${r.lv.id}">${fmt(r.lv.date)}</a>` : '<span class="due amber">None</span>'}</td><td data-label="Next visit">${r.nv ? dueText(r.nv.date) : can('clients.manage') ? `<button class="btn sm" data-act="visitNew" data-org="${r.o.id}">Plan</button>` : '—'}</td>
      <td>${r.o.id === S.ui.org ? badge('Open now', 'blue') : `<button class="btn sm" data-act="openClient" data-id="${r.o.id}">Open</button>`}</td></tr>`).join('')}
    </tbody></table></div></div></div>`;
}
const orgSitesOf = id => S.sites.filter(s => s.org === id);

/* ---------------- Visit reports ---------------- */
function visitsHtml(q) { const V = (S.visits || []).filter(v => myOrgs().some(o => o.id === v.org)).sort((a, b) => b.date.localeCompare(a.date));
  const F = { forg: { all: 'All clients', list: () => myOrgs().map(o => ({ value: o.id, label: o.short || o.name })), test: (v, x) => v.org === x }, fstatus: { all: 'All statuses', list: () => ['Planned', 'In progress', 'Completed'].map(s => ({ value: s, label: s })), test: (v, x) => v.status === x } }, rows = regFilter(V, q, F);
  return `<div class="card">${regFilterBar('#/clients/visits', q, V, rows.length, F, 'Search client, purpose, consultant…')}<div class="card-body flush">${rows.length ? `<div class="table-wrap"><table class="tbl stackable"><thead><tr><th>Visit</th><th>Client / branch</th><th>Date</th><th>Consultant</th><th>Findings</th><th>Status</th></tr></thead><tbody>${rows.map(v => `<tr class="rowlink" data-href="#/clients/${v.id}"><td data-label="Visit"><span class="mono">${v.id}</span><div class="t-title">${esc(v.purpose)}</div></td><td data-label="Client">${esc(orgOf(v.org).short)}<div class="t-sub">${esc(v.site === 'ALL' ? 'All branches' : sname(v.site))}</div></td><td data-label="Date">${v.status === 'Planned' ? dueText(v.date) : fmt(v.date)}</td><td data-label="Consultant">${esc(pname(v.consultant))}</td><td data-label="Findings">${(v.findings || []).length || '—'}</td><td data-label="Status">${badge(v.status, v.status === 'Completed' ? 'green' : v.status === 'Planned' ? 'blue' : 'amber')}</td></tr>`).join('')}</tbody></table></div>` : emptyList('No visits yet. Plan a visit to a client.')}</div></div>`; }
ACT.visitNew = (el) => { const org = (el && el.dataset && el.dataset.org) || S.ui.org; openModal({ title: 'Plan a visit', body: `<div class="form-grid">
    ${fld({ name: 'org', label: 'Client', type: 'select', options: opts(myOrgs().map(o => ({ value: o.id, label: o.name })), org), required: true, full: true })}
    ${fld({ name: 'site', label: 'Branch', type: 'select', options: opts([{ value: 'ALL', label: 'All branches' }].concat(orgSitesOf(org).map(s => ({ value: s.id, label: s.name }))), 'ALL') })}${fld({ name: 'date', label: 'Date', type: 'date', value: addDays(TODAY, 7), required: true })}
    ${fld({ name: 'purpose', label: 'Purpose', value: 'Monthly compliance visit', required: true, full: true })}</div>`,
  onOpen: m => { const o = m.querySelector('[name=org]'); o.addEventListener('change', () => { m.querySelector('[name=site]').innerHTML = opts([{ value: 'ALL', label: 'All branches' }].concat(orgSitesOf(o.value).map(s => ({ value: s.id, label: s.name }))), 'ALL'); }); },
  buttons: [{ label: 'Plan visit', cls: 'primary', onClick: m => { if (!validateForm(m)) return false; const v = readForm(m); S.visits = S.visits || []; const x = { id: nextId('VIS-', 'visits'), org: v.org, site: v.site, date: v.date, purpose: v.purpose, consultant: S.ui.user, status: 'Planned', attendees: '', areas: [], findings: [], summary: '', nextDate: '' }; S.visits.push(x); log(`Planned visit ${x.id} to ${orgOf(v.org).short} on ${fmt(v.date)}`, '#/clients/' + x.id); save(); navigate('#/clients/' + x.id); } }] }); };
const VSIG = { con: null, cli: null };
function visitDetail(id) {
  const v = byId('visits', id); if (!v || !myOrgs().some(o => o.id === v.org)) return ROUTES.notfound(); const o = orgOf(v.org), edit = v.status !== 'Completed' && (v.consultant === S.ui.user || can('clients.manage'));
  const acts = S.actions.filter(a => a.source === 'Consultant visit' && a.sourceId === v.id);
  const html = `<div class="status-hero"><div><div class="sh-id">${v.id} · ${esc(o.name)} · ${esc(v.site === 'ALL' ? 'All branches' : sname(v.site))}</div><h1 style="margin:2px 0 6px">${esc(v.purpose)}</h1><div class="btn-row">${badge(v.status, v.status === 'Completed' ? 'green' : v.status === 'Planned' ? 'blue' : 'amber')} <span class="tag">${fmt(v.date)} · ${esc(pname(v.consultant))}</span></div></div>
    <div class="sh-actions">${edit && v.status === 'Planned' ? `<button class="btn primary" data-act="visitStart" data-id="${v.id}">Start visit</button>` : ''}${v.status === 'Completed' ? `<button class="btn primary" data-act="visitPdf" data-id="${v.id}">${icon('download', 'sm')} Visit report (PDF)</button>` : ''}${v.org !== S.ui.org ? `<button class="btn" data-act="openClient" data-id="${v.org}">Open ${esc(o.short)}</button>` : ''}</div></div>
  ${v.status === 'Planned' ? `<div class="alert info">${icon('calendar')}<div>Planned for ${fmt(v.date)}. Start the visit on the day to record what you checked and your findings.</div></div>` : `
  <div class="detail"><div class="stack">
    <div class="card"><div class="card-head"><h2>What was checked</h2></div><div class="card-body">${edit ? `<div class="chk-row">${VISIT_AREAS.map((a, i) => `<label class="check"><input type="checkbox" data-varea="${v.id}" data-i="${i}" ${(v.areas || []).includes(a) ? 'checked' : ''}> <span>${a}</span></label>`).join('')}</div>` : (v.areas || []).map(a => `<span class="tag">${esc(a)}</span>`).join(' ') || '—'}</div></div>
    <div class="card"><div class="card-head"><h2>Findings</h2>${edit ? `<button class="btn sm" data-act="visitFinding" data-id="${v.id}">${icon('plus', 'sm')} Add finding</button>` : ''}</div><div class="card-body flush">${(v.findings || []).length ? `<div class="table-wrap"><table class="tbl stackable"><thead><tr><th>Finding</th><th>Priority</th><th>Corrective action</th></tr></thead><tbody>${v.findings.map(f => { const a = f.action && byId('actions', f.action); return `<tr><td data-label="Finding"><b>${esc(f.text)}</b>${f.area ? `<div class="t-sub">${esc(f.area)}</div>` : ''}</td><td data-label="Priority">${badge(f.priority, f.priority === 'High' || f.priority === 'Critical' ? 'red' : f.priority === 'Medium' ? 'amber' : 'grey', true)}</td><td data-label="Action">${a ? `<span class="mono">${a.id}</span> ${sbadge(a.status)}<div class="t-sub">${esc(withOrg(v.org, () => pname(a.owner)))} · due ${fmt(a.due)}</div>` : '<span class="muted">Observation only</span>'}</td></tr>`; }).join('')}</tbody></table></div>` : '<div class="card-body muted">No findings recorded.</div>'}</div></div>
    <div class="card"><div class="card-head"><h2>Summary and sign-off</h2></div><div class="card-body">${edit ? `<div class="form-grid">
      ${fld({ name: 'attendees', label: 'Met with (client representatives)', value: v.attendees || '', full: true })}${fld({ name: 'summary', label: 'Summary — what is going well and what needs attention', type: 'textarea', rows: 4, value: v.summary || '', full: true })}${fld({ name: 'nextDate', label: 'Next visit', type: 'date', value: v.nextDate || addMonths(v.date, 1) })}
      <div class="field full" id="vConF"><label for="vCon">Consultant signature<span class="req">*</span></label><div class="sig-wrap"><canvas id="vCon" class="sig-pad"></canvas><div class="sig-foot"><span>${esc(pname(v.consultant))}</span><button type="button" class="btn sm" data-act="vSigClear" data-k="con">Clear</button></div></div></div>
      <div class="field full" id="vCliF"><label for="vCli">Client representative signature</label><div class="sig-wrap"><canvas id="vCli" class="sig-pad"></canvas><div class="sig-foot"><span>Client representative</span><button type="button" class="btn sm" data-act="vSigClear" data-k="cli">Clear</button></div></div></div></div>
      <div class="btn-row mt-s"><button class="btn primary" data-act="visitComplete" data-id="${v.id}">${icon('check', 'sm')} Complete visit and send the report</button></div>`
      : `<div class="kv"><div>Met with</div><div>${esc(v.attendees || '—')}</div><div>Summary</div><div style="white-space:pre-wrap">${esc(v.summary || '—')}</div><div>Next visit</div><div>${v.nextDate ? fmt(v.nextDate) : '—'}</div><div>Consultant</div><div>${v.sigCon ? `<span class="sig-show"><img src="${v.sigCon}" alt="Consultant signature"><small>${esc(pname(v.consultant))}</small></span>` : '—'}</div><div>Client</div><div>${v.sigCli ? `<span class="sig-show"><img src="${v.sigCli}" alt="Client signature"><small>${esc(v.attendees || '')}</small></span>` : '<span class="muted">Not signed</span>'}</div></div>`}</div></div>
  </div><div class="stack"><div class="card"><div class="card-head"><h2>Client at the time of the visit</h2></div><div class="card-body">${(() => { const r = clientStats(o); return `<div class="kv"><div>Control score</div><div>${v.snapshot ? v.snapshot.score : r.c.overall}%</div><div>Legal compliance</div><div>${(v.snapshot ? v.snapshot.legal : r.L.pct) ?? '—'}%</div><div>Overdue actions</div><div>${v.snapshot ? v.snapshot.overdue : r.c.overdueActions}</div><div>Open incidents</div><div>${v.snapshot ? v.snapshot.incidents : r.c.openIncidents}</div></div>`; })()}</div></div></div></div>`}`;
  return { title: v.id, nav: 'clients', crumbs: [['My clients', '#/clients/visits'], [v.id, '#']], html, after: edit && v.status === 'In progress' ? () => { VSIG.con = null; VSIG.cli = null; initSigPad('vCon', VSIG, 'con', 'vConF'); initSigPad('vCli', VSIG, 'cli', 'vCliF'); } : null };
}
document.addEventListener('change', e => { const t = e.target; if (t.dataset && t.dataset.varea) { const v = byId('visits', t.dataset.varea), a = VISIT_AREAS[+t.dataset.i]; v.areas = (v.areas || []).filter(x => x !== a); if (t.checked) v.areas.push(a); save(); } });
document.addEventListener('input', e => { const t = e.target; if (!/^#\/clients\/VIS-/.test(location.hash) || !['attendees', 'summary', 'nextDate'].includes(t.name)) return; const v = byId('visits', location.hash.split('/')[2]); if (v && v.status === 'In progress') { v[t.name] = t.value; save(); } });
ACT.vSigClear = (el) => { VSIG[el.dataset.k] = null; const c = document.getElementById(el.dataset.k === 'con' ? 'vCon' : 'vCli'); if (c) c.getContext('2d').clearRect(0, 0, c.width, c.height); };
ACT.visitStart = (el) => { const v = byId('visits', el.dataset.id); v.status = 'In progress'; v.date = TODAY; log(`Started visit ${v.id}`, '#/clients/' + v.id); save(); rerender(); };
ACT.visitFinding = (el) => { const v = byId('visits', el.dataset.id); withOrg(v.org, () => openModal({ title: 'Add a finding', sub: orgOf(v.org).name, body: `<div class="form-grid">
    ${fld({ name: 'text', label: 'Finding', type: 'textarea', rows: 2, required: true, full: true })}${fld({ name: 'area', label: 'Area', type: 'select', options: opts(VISIT_AREAS) })}${fld({ name: 'priority', label: 'Priority', type: 'select', options: opts(['Critical', 'High', 'Medium', 'Low'], 'Medium') })}
    ${fld({ name: 'raise', label: 'Raise a corrective action at the client', type: 'checkbox', value: true, full: true })}${fld({ name: 'owner', label: 'Action owner (client)', type: 'select', options: opts(S.people.filter(p => p.org === v.org && p.sysRole && p.status !== 'Deactivated').map(p => ({ value: p.id, label: `${p.name} — ${p.jobTitle}` })), (S.people.find(p => p.org === v.org && p.sysRole === 'HSEQ Manager') || {}).id || '', '— Select —') })}
    ${fld({ name: 'action', label: 'Required corrective action', full: true })}</div>`,
  buttons: [{ label: 'Add', cls: 'primary', onClick: m => { if (!validateForm(m)) return false; const x = readForm(m); if (x.raise && !x.owner) { toast('Choose the action owner at the client.', 'error'); return false; }
    let act = null; if (x.raise) act = withOrg(v.org, () => createAction({ source: 'Consultant visit', sourceId: v.id, title: x.text.slice(0, 140), action: x.action, owner: x.owner, priority: x.priority, site: v.site === 'ALL' ? (orgSitesOf(v.org)[0] || {}).id : v.site })).id;
    (v.findings = v.findings || []).push({ text: x.text, area: x.area, priority: x.priority, action: act }); log(`Visit ${v.id}: finding recorded${act ? ' — ' + act : ''}`, '#/clients/' + v.id); save(); rerender(); } }] })); };
ACT.visitComplete = (el) => { const v = byId('visits', el.dataset.id); ['attendees', 'summary', 'nextDate'].forEach(k => { const f = document.querySelector(`#content [name=${k}]`); if (f) v[k] = f.value.trim(); }); if (!(v.summary || '').trim()) { toast('Write the summary of the visit.', 'error'); return; } if (!VSIG.con) { toast('Sign the visit report.', 'error'); document.getElementById('vConF').classList.add('invalid'); return; }
  const r = clientStats(orgOf(v.org)); Object.assign(v, { status: 'Completed', sigCon: VSIG.con, sigCli: VSIG.cli, completed: nowTs(), snapshot: { score: r.c.overall, legal: r.L.pct, overdue: r.c.overdueActions, incidents: r.c.openIncidents } });
  if (v.nextDate) { S.visits.push({ id: nextId('VIS-', 'visits'), org: v.org, site: v.site, date: v.nextDate, purpose: v.purpose, consultant: v.consultant, status: 'Planned', attendees: '', areas: [], findings: [], summary: '', nextDate: '' }); }
  const to = S.people.filter(p => p.org === v.org && ['HSEQ Manager', 'Managing Director'].includes(p.sysRole) && p.status !== 'Deactivated').map(p => p.id);
  withOrg(v.org, () => queueEmail(to, 'summary', `Consultant visit report: ${orgOf(v.org).short} — ${fmt(v.date)}`, `${pname(v.consultant)} visited ${orgOf(v.org).name} on ${fmt(v.date)} (${v.purpose}).\n\n${v.summary}\n\nFindings: ${(v.findings || []).length}; corrective actions raised: ${(v.findings || []).filter(f => f.action).length}.${v.nextDate ? '\nNext visit: ' + fmt(v.nextDate) + '.' : ''}`, '#/clients/' + v.id));
  log(`Completed visit ${v.id} to ${orgOf(v.org).short}`, '#/clients/' + v.id); save(); toast('Visit completed — the report was sent to the client\'s management.'); rerender(); };
ACT.visitPdf = async (el) => { const v = byId('visits', el.dataset.id), o = orgOf(v.org);
  try { const { PDFDocument, StandardFonts, rgb } = await ensurePdfLib(); const pdf = await PDFDocument.create(), R = await pdf.embedFont(StandardFonts.Helvetica), B = await pdf.embedFont(StandardFonts.HelveticaBold);
    let pg = pdf.addPage([595, 842]), y = 800; const M = 48, mute = rgb(0.4, 0.45, 0.55), ink = rgb(0.06, 0.1, 0.2);
    const T = (s, o2 = {}) => { const size = o2.size || 10, f = o2.bold ? B : R; let line = ''; const out = []; pdfSafe(s).split(' ').forEach(w => { const t = line ? line + ' ' + w : w; if (f.widthOfTextAtSize(t, size) > 595 - 2 * M && line) { out.push(line); line = w; } else line = t; }); if (line) out.push(line);
      out.forEach(l => { if (y < 70) { pg = pdf.addPage([595, 842]); y = 800; } pg.drawText(l, { x: M, y, size, font: f, color: o2.color || ink }); y -= size + 4; }); y -= o2.after || 2; };
    T('VDW Health & Safety — consultant visit report', { color: mute }); T(o.name, { bold: true, size: 17, after: 4 }); T(`${v.purpose} · ${fmt(v.date)} · ${v.site === 'ALL' ? 'All branches' : sname(v.site)} · ${pname(v.consultant)}`, { color: mute, after: 10 });
    T('Met with: ' + (v.attendees || '—')); T('Areas checked: ' + ((v.areas || []).join(', ') || '—'), { after: 8 });
    T('Summary', { bold: true, size: 12 }); (v.summary || '').split('\n').forEach(l => T(l)); y -= 6;
    T(`Findings (${(v.findings || []).length})`, { bold: true, size: 12 }); (v.findings || []).forEach((f, i) => { const a = f.action && byId('actions', f.action); T(`${i + 1}. [${f.priority}] ${f.text}${f.area ? ' (' + f.area + ')' : ''}${a ? ' — action ' + a.id + ', due ' + fmt(a.due) : ' — observation'}`); });
    y -= 6; T(`Next visit: ${v.nextDate ? fmt(v.nextDate) : '—'}`, { after: 10 });
    for (const [lbl, sg] of [['Consultant', v.sigCon], ['Client representative', v.sigCli]]) { T(lbl, { bold: true }); if (sg) { try { const im = await pdf.embedPng(Uint8Array.from(atob(sg.split(',')[1]), c => c.charCodeAt(0))); const s = Math.min(160 / im.width, 44 / im.height); pg.drawImage(im, { x: M, y: y - 46, width: im.width * s, height: im.height * s }); y -= 54; } catch (e) { /* optional */ } } else T('Not signed', { color: mute }); }
    T('Figures come from the records in the system; they do not guarantee legal compliance.', { size: 8, color: mute });
    if (await saveFile(`Visit_${v.id}_${o.short.replace(/\W+/g, '_')}_${v.date}.pdf`, new Blob([await pdf.save()], { type: 'application/pdf' }))) toast('Visit report downloaded.');
  } catch (e) { console.error(e); toast('The PDF could not be made: ' + esc(e.message), 'error'); } };

/* ---------------- Template library: copy a client's set-up ---------------- */
const LIB_PARTS = [
  ['legal', 'Legal requirements', 'copied as "Pending assessment", without assessments or evidence'],
  ['training', 'Courses and training requirements', 'job titles must match the new client\'s'],
  ['ppe', 'PPE types and requirements', 'stock is not copied'],
  ['risk', 'Risk assessments', 'copied as drafts to review for the new client\'s branches'],
  ['audits', 'Company audit checklists', 'copied as drafts to approve'],
  ['contractors', 'Contractor kinds of work and documents', 'shared across clients']];
function libraryPageHtml() {
  const count = (o, k) => k === 'legal' ? (S.legalReqs || []).filter(r => r.org === o).length : k === 'training' ? (S.courses || []).filter(c => c.org === o).length : k === 'ppe' ? (S.ppeTypes || []).filter(t => t.org === o).length : k === 'risk' ? (S.riskAssessments || []).filter(a => a.org === o && a.status !== 'Superseded').length : k === 'audits' ? (S.auditTemplates || []).filter(t => t.org === o).length : (S.config.contractorReqs || []).length;
  return `<div class="alert info">${icon('info')}<div>Set up a new client from one that is already set up: copy its legal requirements, training, PPE, risk assessments and audit checklists. Everything copied starts as a draft or "pending" so it is reviewed for the new client. The VDW starter audit checklists, appointment types and the risk matrix are already shared by all clients.</div></div>
  <div class="card"><div class="card-head"><h2>What each client has set up</h2></div><div class="card-body flush"><div class="table-wrap"><table class="tbl stackable"><thead><tr><th>Item</th>${myOrgs().map(o => `<th>${esc(o.short)}</th>`).join('')}<th>Note</th></tr></thead><tbody>${LIB_PARTS.map(([k, label, note]) => `<tr><td data-label="Item"><b>${label}</b></td>${myOrgs().map(o => `<td data-label="${esc(o.short)}">${count(o.id, k)}</td>`).join('')}<td data-label="Note" class="t-sub">${note}</td></tr>`).join('')}</tbody></table></div></div></div>
  ${can('clients.manage') ? `<div class="btn-row mt"><button class="btn primary" data-act="libCopy">${icon('docs', 'sm')} Copy a set-up to a client</button></div>` : ''}`;
}
ACT.libCopy = () => openModal({ title: 'Copy a set-up to a client', size: 'wide', body: `<div class="form-grid">
    ${fld({ name: 'from', label: 'Copy from', type: 'select', options: opts(myOrgs().map(o => ({ value: o.id, label: o.name })), S.ui.org), required: true })}${fld({ name: 'to', label: 'Copy to', type: 'select', options: opts(myOrgs().map(o => ({ value: o.id, label: o.name })), (myOrgs().find(o => o.id !== S.ui.org) || {}).id), required: true })}
    <div class="field full"><label>What to copy</label><div class="chk-col">${LIB_PARTS.filter(p => p[0] !== 'contractors').map(([k, label, note]) => `<label class="check"><input type="checkbox" name="lib_${k}" checked> <span><b>${label}</b> <span class="t-sub">— ${note}</span></span></label>`).join('')}</div></div></div>`,
  buttons: [{ label: 'Copy', cls: 'primary', onClick: m => { const v = readForm(m); if (v.from === v.to) { toast('Choose two different clients.', 'error'); return false; }
    const to = v.to, site0 = (orgSitesOf(to)[0] || {}).id, n = {}, clone = x => JSON.parse(JSON.stringify(x));
    if (v.lib_legal) { n.legal = 0; (S.legalReqs || []).filter(r => r.org === v.from).forEach(r => { if ((S.legalReqs || []).some(x => x.org === to && x.leg === r.leg && x.item === r.item && x.title === r.title)) return; const c = clone(r); Object.assign(c, { id: nextId('LR-', 'legalReqs'), org: to, sites: ['ALL'], owner: null, applicability: 'Pending assessment', applicReason: '', assessments: [], evidence: [], created: TODAY, createdBy: S.ui.user, copiedFrom: r.id }); delete c.reassess; delete c.demo; S.legalReqs.push(c); n.legal++; }); }
    if (v.lib_training) { n.training = 0; const map = {}; (S.courses || []).filter(c => c.org === v.from).forEach(c => { const ex = S.courses.find(x => x.org === to && x.name === c.name); if (ex) { map[c.id] = ex.id; return; } const k = clone(c); k.id = nextId('CRS-', 'courses'); k.org = to; S.courses.push(k); map[c.id] = k.id; n.training++; });
      (S.trainingReqs || []).filter(r => r.org === v.from && r.by !== 'activity').forEach(r => { const k = clone(r); k.id = nextId('TRQ-', 'trainingReqs'); k.org = to; k.course = map[r.course]; if (k.course && !S.trainingReqs.some(x => x.org === to && x.course === k.course && x.by === k.by && x.value === k.value)) S.trainingReqs.push(k); }); }
    if (v.lib_ppe) { n.ppe = 0; const map = {}; (S.ppeTypes || []).filter(t => t.org === v.from).forEach(t => { const ex = S.ppeTypes.find(x => x.org === to && x.name === t.name); if (ex) { map[t.id] = ex.id; return; } const k = clone(t); Object.assign(k, { id: nextId('PPE-', 'ppeTypes'), org: to, stock: null }); S.ppeTypes.push(k); map[t.id] = k.id; n.ppe++; });
      (S.ppeReqs || []).filter(r => r.org === v.from && r.by !== 'activity').forEach(r => { const k = clone(r); Object.assign(k, { id: nextId('PRQ-', 'ppeReqs'), org: to, ppe: map[r.ppe], ra: null }); if (k.ppe) S.ppeReqs.push(k); }); }
    if (v.lib_risk) { n.risk = 0; (S.riskAssessments || []).filter(a => a.org === v.from && a.status !== 'Superseded').forEach(a => { const k = clone(a); Object.assign(k, { id: nextId('RA-', 'riskAssessments'), org: to, site: site0, status: 'Draft', version: 1, reviews: [], evidence: [], participants: [], approvedBy: null, approvedOn: null, reviewDate: '', asset: null, substance: null, created: TODAY, copiedFrom: a.id }); k.rows.forEach(r => { r.hazard = null; delete r.accepted; delete r.escalated; (r.controls || []).forEach(c => { c.status = 'Planned'; c.evidence = []; c.owner = ''; delete c.action; }); }); S.riskAssessments.push(k); n.risk++; }); }
    if (v.lib_audits) { n.audits = 0; (S.auditTemplates || []).filter(t => t.org === v.from).forEach(t => { const k = clone(t); const cur = atCurrent(t) || atDraft(t); Object.assign(k, { id: nextId('ATPL-', 'auditTemplates', 3), org: to, docNumber: t.docNumber + '-C', revisions: [Object.assign(clone(cur), { rev: 1, status: 'Draft', author: S.ui.user, changeNote: 'Copied from ' + orgOf(v.from).short })] }); S.auditTemplates.push(k); n.audits++; }); }
    log(`Copied the set-up of ${orgOf(v.from).short} to ${orgOf(to).short}: ${Object.entries(n).map(([k, x]) => x + ' ' + k).join(', ')}`, '#/clients/library'); save(); toast(`Copied to ${orgOf(to).short}: ${Object.entries(n).map(([k, x]) => `${x} ${k}`).join(', ')}.`); rerender(); } }] });

