myTasks = function () { const out = _myTasksBeforeCons(); (S.visits || []).filter(v => v.consultant === S.ui.user && v.status !== 'Completed' && daysTo(v.date) <= 7).forEach(v => out.push({ title: `Client visit: ${orgOf(v.org).short} — ${v.purpose}`, sub: v.status === 'In progress' ? 'Complete the visit report' : 'Planned ' + fmt(v.date), link: '#/clients/' + v.id, sev: daysTo(v.date) < 0 ? 'red' : 'blue' })); return out; };
