  if (!byId('visits', 'VIS-002')) S.visits.push({ id: 'VIS-002', org: 'ORG-1', site: 'S-JHB', date: addDays(TODAY, 3), purpose: 'Monthly compliance visit', consultant: 'P-006', status: 'Planned', attendees: '', areas: [], findings: [], summary: '', nextDate: '' });
